def match(orders):
    trades = []
    buy_book = []    # [(price, arrival_time, id, qty)] - sorted by price desc, then arrival_time asc
    sell_book = []   # [(price, arrival_time, id, qty)] - sorted by price asc, then arrival_time asc
    order_map = {}   # {id: (side, price, arrival_time)} to track resting orders

    arrival_time = [0]

    def insert_buy(price, id, qty):
        arrival_time[0] += 1
        idx = 0
        for i, (p, t, _, _) in enumerate(buy_book):
            if p > price or (p == price and t < arrival_time[0]):
                idx = i
            else:
                break
        buy_book.insert(idx, (price, arrival_time[0], id, qty))
        order_map[id] = ('buy', price, arrival_time[0])

    def insert_sell(price, id, qty):
        arrival_time[0] += 1
        idx = 0
        for i, (p, t, _, _) in enumerate(sell_book):
            if p < price or (p == price and t < arrival_time[0]):
                idx = i
            else:
                break
        sell_book.insert(idx, (price, arrival_time[0], id, qty))
        order_map[id] = ('sell', price, arrival_time[0])

    def match_buy(price, id, qty, is_ioc_or_market):
        nonlocal trades
        remaining_qty = qty

        while remaining_qty > 0 and sell_book:
            sell_price, sell_time, sell_id, sell_qty = sell_book[0]

            if sell_price > price:
                break

            trade_qty = min(remaining_qty, sell_qty)
            trades.append([id, sell_id, sell_price, trade_qty])

            remaining_qty -= trade_qty
            sell_book[0] = (sell_price, sell_time, sell_id, sell_qty - trade_qty)

            if sell_book[0][3] == 0:
                sell_book.pop(0)
                del order_map[sell_id]
            else:
                order_map[sell_id] = ('sell', sell_price, sell_time)

        if remaining_qty > 0 and not is_ioc_or_market:
            insert_buy(price, id, remaining_qty)

    def match_sell(price, id, qty, is_ioc_or_market):
        nonlocal trades
        remaining_qty = qty

        while remaining_qty > 0 and buy_book:
            buy_price, buy_time, buy_id, buy_qty = buy_book[0]

            if buy_price < price:
                break

            trade_qty = min(remaining_qty, buy_qty)
            trades.append([buy_id, id, buy_price, trade_qty])

            remaining_qty -= trade_qty
            buy_book[0] = (buy_price, buy_time, buy_id, buy_qty - trade_qty)

            if buy_book[0][3] == 0:
                buy_book.pop(0)
                del order_map[buy_id]
            else:
                order_map[buy_id] = ('buy', buy_price, buy_time)

        if remaining_qty > 0 and not is_ioc_or_market:
            insert_sell(price, id, remaining_qty)

    for order in orders:
        order_type = order[0]

        if order_type == 'limit':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(price, id, qty, False)
            else:
                match_sell(price, id, qty, False)

        elif order_type == 'ioc':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(price, id, qty, True)
            else:
                match_sell(price, id, qty, True)

        elif order_type == 'market':
            _, id, side, qty = order
            if side == 'buy':
                match_buy(float('inf'), id, qty, True)
            else:
                match_sell(0, id, qty, True)

        elif order_type == 'cancel':
            _, id = order
            if id in order_map:
                side, price, time = order_map[id]
                if side == 'buy':
                    buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != id]
                else:
                    sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != id]
                del order_map[id]

    return trades

